  ok(ClanConfig.INSTANCE.prepTicks==6000,"five minute prep default");ok(ClanConfig.INSTANCE.bundle.containsKey("minecraft:arrow")&&ClanConfig.INSTANCE.bundle.containsKey("minecraft:cooked_beef"),"mixed supplies and equipment");
  String wire=ClanState.row("MATE","Nombre\t extraño\n","-20.4");ok(ClanState.rows(wire).get(0)[1].equals("Nombre\t extraño\n"),"snapshot separators cannot inject rows");net.minecraft.network.FriendlyByteBuf buf=new net.minecraft.network.FriendlyByteBuf();ClanPacket p=new ClanPacket(ClanPacket.DECLARE,"Medics","food",1);ClanPacket.CODEC.encode(buf,p);ok(p.equals(ClanPacket.CODEC.decode(buf)),"actual packet codec roundtrip");
  Match m=new Match();War w=m.declare(true);ok(w!=null&&m.fa.war.isWarActive&&m.fb.war.isWarActive,"both clans enter siege including basic teams");ok(w.ready==6000&&w.end>w.ready,"persisted preparation and duration");ok(!Clans.canLaunch(m.a,false),"launch blocked before declaration preparation");ok(Clans.canLaunch(m.a,true),"authorized draft allowed during preparation");ok(!Clans.territoryAllowed(m.s.manager,m.fb.id),"territory locked during preparation");m.kill();ok(w.scoreA==0,"kills during preparation cannot farm scores");
  ok(WarOperationUtil.meetsOnlineRequirement(m.fb,m.s),"transformed native online rule accepts civilian member");m.s.time=w.ready;ok(Clans.canLaunch(m.a,false),"siege launch after five minutes");ok(Clans.territoryAllowed(m.s.manager,m.fb.id),"online defender unlocks territory gate");OperationData op=new OperationData();op.attackerFactionId=m.fa.id;op.defenderFactionId=m.fb.id;OperationAttack atk=new OperationAttack(4,-2);op.attacks.add(atk);op.attackerAssignments.put(m.a.uuid,atk.chunkLong());m.fa.war.activeOperation=op;m.fb.claims.add(atk.chunkLong());
  ok(Clans.operationAllowed(op),"operation permitted with online defender");ok(WarOperationUtil.canPlayerAttack(op,m.fa.id,m.a.uuid,atk.chunkLong()),"transformed native assigned attacker allowed");ok(WarOperationUtil.findActiveOperationForChunk(m.s.manager,m.fb.id,atk.chunkLong())==op,"native central claim bypass retains target matching");ok(!WarOperationUtil.canPlayerAttack(op,m.fa.id,UUID.randomUUID(),atk.chunkLong()),"unassigned player cannot bypass claims");ok(WarOperationUtil.addBlockCredit(m.s.manager,op,atk.chunkLong(),1),"native block credit online");
  m.s.online.remove(m.b.uuid);ok(!Clans.canLaunch(m.a,false),"offline defender blocks new launch");ok(!Clans.operationAllowed(op),"existing operation stops immediately on disconnect");ok(!Clans.operationTick(m.s,m.s.manager,m.fa),"capture timer pauses while defender offline");ok(!WarOperationUtil.canPlayerAttack(op,m.fa.id,m.a.uuid,atk.chunkLong()),"native attack permission revoked immediately offline");ok(WarOperationUtil.findActiveOperationForChunk(m.s.manager,m.fb.id,atk.chunkLong())==null,"native explosions/claim central bypass closed offline");ok(!WarOperationUtil.addBlockCredit(m.s.manager,op,atk.chunkLong(),1),"no block credit offline");m.s.online.put(m.b.uuid,m.b);ok(Clans.operationTick(m.s,m.s.manager,m.fa),"operation resumes on reconnection");
  m.kill();ok(w.scoreA==5,"enemy player kill awards points");m.kill();ok(w.scoreA==5,"same victim cooldown blocks repeated immediate kills");Clans.death(new Death(m.b,new Hit(m.a),true));ok(w.scoreA==5,"canceled death cannot award points");Clans.death(new Death(m.a,new Hit(m.a),false));ok(w.scoreA==5,"self kill cannot award points");m.s.time+=ClanConfig.INSTANCE.killCooldownTicks;m.kill();ok(w.scoreA==10,"victim scores after configured cooldown");m.s.time+=ClanConfig.INSTANCE.killCooldownTicks;m.kill();m.s.time+=ClanConfig.INSTANCE.killCooldownTicks;m.kill();ok(w.scoreA==15,"per account scored kill limit");
  Clans.captured(m.s.manager,m.fa,m.fb,atk.chunkLong());Clans.captured(m.s.manager,m.fa,m.fb,atk.chunkLong());ok(w.scoreA==35,"capture points awarded once per side and chunk");atk.state=OperationAttack.State.DEFENDED;Clans.operationEnded(m.s,m.s.manager,m.fa,m.fb,op);Clans.operationEnded(m.s,m.s.manager,m.fa,m.fb,op);ok(w.scoreB==10,"defense reward objective is idempotent");op.state=OperationData.State.PREPARING;Clans.operationEnded(m.s,m.s.manager,m.fa,m.fb,op);ok(w.scoreB==10,"canceled prep cannot generate defense points");op.state=OperationData.State.PREPARING;op.prepTimeRemaining=600;Clans.operationLaunched(m.a);ok(op.prepTimeRemaining==0,"no duplicate ten-minute native preparation after global prep");
  CompoundTag saved=new CompoundTag();Clans.save(m.s.manager,saved);MinecraftServer restart=new MinecraftServer();restart.manager.factions.put(m.fa.id,m.fa);restart.manager.factions.put(m.fb.id,m.fb);restart.online.put(m.a.uuid,m.a);restart.online.put(m.b.uuid,m.b);Clans.load(restart.manager,saved);Clans.bind(restart.manager,restart);War restored=Clans.state(restart.manager).war(m.fa.id);ok(restored.scoreA==35&&restored.scoreB==10,"score survives save and restart");ok(restored.ready==6000&&restored.end==w.end,"timers survive restart");ok(restored.victimCount.get(m.b.uuid)==3&&restored.objectives.size()==2,"anti farm and objective ledger survives restart");
  m.s.time=w.end;Clans.tick(m.s);ok(Clans.state(m.s.manager).wars.isEmpty(),"duration automatically closes war");ok(!m.fa.war.isWarActive&&!m.fb.war.isWarActive,"native flags and operations clear on end");Profile pa=Clans.state(m.s.manager).profile(m.fa.id),pb=Clans.state(m.s.manager).profile(m.fb.id);ok(pa.lastResult.contains("Victoria")&&pb.lastResult.contains("Derrota"),"score determines winner and history");ok(pa.rewards.get("minecraft:arrow")>pb.rewards.get("minecraft:arrow"),"winner gets larger score based mixed rewards");int bank=pa.rewards.values().stream().mapToInt(Integer::intValue).sum();Clans.tick(m.s);ok(pa.rewards.values().stream().mapToInt(Integer::intValue).sum()==bank,"finished war cannot pay twice");
  m.a.inventory.capacity=0;Clans.action(m.a,new ClanPacket(ClanPacket.CLAIM,"","",0));ok(pa.rewards.values().stream().mapToInt(Integer::intValue).sum()==bank,"full inventory preserves reward bank");m.a.inventory.capacity=3;Clans.action(m.a,new ClanPacket(ClanPacket.CLAIM,"","",0));ok(pa.rewards.values().stream().mapToInt(Integer::intValue).sum()==bank-3&&m.a.inventory.received==3,"partial inventory delivery deducts only received items");m.a.inventory.capacity=100000;for(int i=0;i<8;i++)Clans.action(m.a,new ClanPacket(ClanPacket.CLAIM,"","",0));ok(pa.rewards.isEmpty()&&m.a.inventory.received==bank,"remaining rewards delivered without duplication");Clans.action(m.a,new ClanPacket(ClanPacket.DECLARE,"Medics","",1));ok(Clans.state(m.s.manager).wars.isEmpty(),"pair truce prevents immediate repeated wars");
  Match sk=new Match();War sw=sk.declare(false);sk.s.time=sw.ready;ok(!Clans.canLaunch(sk.a,false)&&!Clans.territoryAllowed(sk.s.manager,sk.fb.id),"skirmish never enables claims or territory operations");sk.kill();ok(sw.scoreA==5,"skirmish awards player combat points");sk.fb.members.put(sk.b.uuid,FactionRank.CREATOR);Clans.action(sk.b,new ClanPacket(ClanPacket.SURRENDER,"","",0));ok(Clans.state(sk.s.manager).wars.isEmpty()&&Clans.state(sk.s.manager).profile(sk.fa.id).lastResult.contains("Victoria"),"authority surrender finalizes scored skirmish");
  Match zero=new Match();War zw=zero.declare(false);zero.fb.members.put(zero.b.uuid,FactionRank.CREATOR);Clans.action(zero.b,new ClanPacket(ClanPacket.SURRENDER,"","",0));ok(Clans.state(zero.s.manager).profile(zero.fa.id).rewards.isEmpty(),"zero contribution surrender gives no free rewards");
  Match ally=new Match();ally.fa.allies.add(ally.fb.id);ok(ally.declare(true)==null,"allies cannot be declared enemies");ally.fa.allies.clear();ally.fa.allianceCooldown=System.currentTimeMillis()+60000;ok(ally.declare(true)==null,"native alliance break cooldown honored");
  Match unauthorized=new Match();unauthorized.fa.members.put(unauthorized.a.uuid,FactionRank.CITIZEN);ok(unauthorized.declare(true)==null,"citizen cannot declare war");Clans.action(unauthorized.a,new ClanPacket(ClanPacket.PROFILE,"bad","SKULL|Milicia",0));ok(Clans.state(unauthorized.s.manager).profile(unauthorized.fa.id).motto.isEmpty(),"citizen cannot edit identity");
  Match custom=new Match();Clans.action(custom.a,new ClanPacket(ClanPacket.PROFILE,"Stay alive","MEDIC|Rescatistas",0));Profile profile=Clans.state(custom.s.manager).profile(custom.fa.id);ok(profile.motto.equals("Stay alive")&&profile.badge.equals("MEDIC"),"clan customization applies permitted values");Clans.action(custom.a,new ClanPacket(ClanPacket.PROFILE,"bad","INVALID|Rescatistas",0));ok(profile.motto.equals("Stay alive"),"invalid customization cannot partially mutate profile");CompoundTag customSaved=new CompoundTag();profile.rewards.put("missing:medkit",2);Clans.save(custom.s.manager,customSaved);var newManager=new me.danialisntcool.factionfriction.data.FactionManager();Clans.load(newManager,customSaved);ok(Clans.state(newManager).profile(custom.fa.id).motto.equals("Stay alive")&&Clans.state(newManager).profile(custom.fa.id).rewards.get("missing:medkit")==2,"profile and reward bank persist");Clans.action(custom.a,new ClanPacket(ClanPacket.CLAIM,"","",0));ok(profile.rewards.get("missing:medkit")==2,"missing optional reward item preserved until mod restored");
  FFConfig.ADMIN_APPROVED_JUSTIFICATIONS.value=true;Match admin=new Match();ok(admin.declare(true)==null,"server administrative approval requirement blocks unauthorized declarations");admin.a.permission=3;ok(admin.declare(true)!=null,"administrator may declare approved conflict");FFConfig.ADMIN_APPROVED_JUSTIFICATIONS.value=false;
  FFNetwork.snapshots.clear();Clans.snapshot(custom.a,custom.s.manager);var rows=ClanState.rows(FFNetwork.snapshots.get(0).a());ok(rows.stream().filter(r->r[0].equals("MATE")).count()==1,"snapshot only includes own clan positions");ok(rows.stream().noneMatch(r->r[0].equals("MATE")&&r[1].equals(custom.b.getGameProfile().getName())),"rival positions never disclosed");
  Match migrated=new Match();migrated.fa.war.enemyFactionId=migrated.fb.id;migrated.fb.war.enemyFactionId=migrated.fa.id;migrated.fa.war.isWarActive=true;migrated.fb.war.isWarActive=true;Clans.tick(migrated.s);War mw=Clans.state(migrated.s.manager).war(migrated.fa.id);ok(mw!=null&&mw.siege&&mw.ready==6000,"existing native wars migrate with preparation, not orphaned operations");Clans.tick(migrated.s);ok(Clans.state(migrated.s.manager).wars.size()==1,"migration is idempotent");ok(!Clans.territoryAllowed(migrated.s.manager,migrated.fb.id),"migration cannot bypass new preparation");
